/**
 * Reading the published forecast artifacts.
 *
 * The frontend reads JSON that the Python pipeline wrote — it never computes
 * a probability of its own. That separation is deliberate and load-bearing:
 * a number rendered on the page must be traceable to a specific artifact,
 * generated by a specific model version, from a specific corpus. A component
 * that quietly recomputes something is a second model nobody benchmarked.
 *
 * Every accessor here returns `null` rather than a default when the artifact
 * is missing. **Absent data is rendered as absent**, never as zero — a 0%
 * championship probability and "we have not run the forecast" look identical
 * on a page and mean completely different things.
 */

import fs from 'node:fs'
import path from 'node:path'

const PREDICTIONS_DIR = path.join(process.cwd(), 'backend', 'data', 'predictions')
const DIAGNOSTICS_DIR = path.join(process.cwd(), 'backend', 'data', 'diagnostics')

