/** Games grouped by their Eastern calendar date, in schedule order. */
export function groupByDay(games: GameForecast[]): Array<[string, GameForecast[]]> {
  const buckets = new Map<string, GameForecast[]>()
  for (const game of games) {
    // Bucketed on the US Eastern day, matching how the league itself talks
    // about a slate. A UTC bucket splits a normal evening across two dates.
    const day = new Date(new Date(game.date_utc).getTime() - 5 * 3600 * 1000)
      .toISOString()
      .slice(0, 10)
    const existing = buckets.get(day)
    if (existing) existing.push(game)
    else buckets.set(day, [game])
  }
  return Array.from(buckets.entries()).sort((a, b) => a[0].localeCompare(b[0]))
}
